// The cost of one routed call on both sides. Taifoon charges the list price on the key (taifoon.usd_per_1m, USD per 1M tokens);
// NEAR records the call in its own usage at the price its row carries (the same numbers when written by workflow 20).
// metered: the meter line Taifoon recorded for this call (taifoon.meter: provider and our_fee legs, its step at GET /v1/gw/steps/<step>);
// legs_sum_to_list and list_matches_charge say whether the recorded legs add up to what the key was charged.
// settled: what the key paid against the venue's own token counts at the list price (usage_micro = ⌈prompt × in + completion × out⌉, at
// least 1); charge_matches_usage says the charge is that, not the max_tokens reserve (Taifoon settles a keyed call to its usage).
const r = $('One call').first().json; const list = $('List models').first().json.data ?? [];
const m = list.find((x) => x.id === r.model) ?? {}; const p = m.taifoon?.usd_per_1m ?? {}; const inP = Number(p.in ?? 0), outP = Number(p.out ?? 0);
const u = r.usage ?? {}; const cost = ((u.prompt_tokens ?? 0) * inP + (u.completion_tokens ?? 0) * outP) / 1e6;
const sale = r.taifoon?.sale ?? null; const mt = r.taifoon?.meter ?? null;
const leg = (to) => (mt?.legs ?? []).filter((l) => l.to === to).reduce((s, l) => s + Number(l.micro ?? 0), 0);
const metered = mt ? { step: mt.step ?? null, url: mt.url ?? null, served_by: r.taifoon?.served_by ?? null, list_usdc: Number(mt.list_micro ?? 0) / 1e6,
  provider_usdc: leg('provider') / 1e6, our_fee_usdc: leg('our_fee') / 1e6, reseller_markup_usdc: leg('reseller_markup') / 1e6,
  legs_sum_to_list: (mt.legs ?? []).reduce((s, l) => s + Number(l.micro ?? 0), 0) === Number(mt.list_micro ?? -1),
  list_matches_charge: sale ? Number(mt.list_micro) === Number(sale.micro ?? 0) + Number(sale.markup_micro ?? 0) : null } : null;
const usageMicro = Math.max(1, Math.ceil((u.prompt_tokens ?? 0) * inP + (u.completion_tokens ?? 0) * outP));
const st = sale?.settled ?? null;
const settled = sale ? { usage_micro: usageMicro, charged_micro: Number(sale.micro ?? 0), basis: st?.basis ?? null, reserved_micro: st ? Number(st.reserved_micro) : null,
  returned_micro: st ? Number(st.returned_micro) : null, charge_matches_usage: Math.abs(Number(sale.micro ?? 0) - usageMicro) <= 1 } : null;
return [{ json: { model: r.model, answer: r.choices?.[0]?.message?.content ?? null, usage: u, list_price_usd_per_mtok: { in: inP, out: outP }, cost_usd_at_list: Number(cost.toFixed(9)), charged_by_taifoon: sale ? { usdc: sale.usdc, sale_id: sale.id } : null, metered, settled, evidence: sale?.id ?? r.id ?? null } }];
